#include <stdio.h>
#include <string.h>

static unsigned char rar5_signature[] = { 243, 192, 211, 128, 187, 166, 160, 161 };
static const ssize_t rar5_signature_size = sizeof(rar5_signature);

int main() {
    printf("Before XOR: ");
    for (int i = 0; i < rar5_signature_size; i++) {
        printf("%02x ", rar5_signature[i]);
    }
    printf("\n");

    // XOR with 0xA1
    for (int i = 0; i < rar5_signature_size; i++) {
        rar5_signature[i] ^= 0xA1;
    }

    printf("After XOR:  ");
    for (int i = 0; i < rar5_signature_size; i++) {
        printf("%02x ", rar5_signature[i]);
    }
    printf("\n");
    printf("As string: %s\n", rar5_signature);

    // Compare with "Rar!\x1a\x07\x01\x00"
    unsigned char expected[] = "Rar!\x1a\x07\x01\x00";
    printf("Expected:   ");
    for (int i = 0; i < rar5_signature_size; i++) {
        printf("%02x ", expected[i]);
    }
    printf("\n");
    printf("Match: %d\n", memcmp(rar5_signature, expected, rar5_signature_size) == 0);

    return 0;
}
EOF
g++ -o test_signature test_signature.c && ./test_signature

